//! Example 3: Rust Guest Mod (`rust_mod`) for Cross-Language Interoperability.
//!
//! Operates alongside the ISO C99 mod inside the same Bevy `Update` schedule. Resolves
//! `"bam.v0.example::Position.vtable"` and `"bam.v0.example::ColorRgba.vtable"` with
//! [`VTableHeader`] verification and checks [`FfiResult`] returns on every setter call, storing
//! all state per-`World` inside [`GuestPlugin`] (zero process globals).

use bevy_abi_mod_guest::prelude::*;
use core::ffi::{CStr, c_void};

/// Guest mirror of `"example::Position"` (`PositionVTable` generated by `ModComponent`).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, ModComponent)]
#[mod_component(name = "example::Position")]
pub struct Position {
    /// X coordinate.
    pub x: f32,
    /// Y coordinate.
    pub y: f32,
    /// Z coordinate.
    pub z: f32,
}

impl GuestComponent for Position {
    const NAME: &'static CStr = c"example::Position";
    const UUID: ComponentUuid = <Self as ModComponent>::UUID;
}

/// Guest mirror of `"example::ColorRgba"` (`ColorRgbaVTable` generated by `ModComponent`).
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, ModComponent)]
#[mod_component(name = "example::ColorRgba")]
pub struct ColorRgba {
    /// Red channel.
    pub r: f32,
    /// Green channel.
    pub g: f32,
    /// Blue channel.
    pub b: f32,
    /// Alpha channel.
    pub a: f32,
}

impl GuestComponent for ColorRgba {
    const NAME: &'static CStr = c"example::ColorRgba";
    const UUID: ComponentUuid = <Self as ModComponent>::UUID;
}

/// Per-`World` guest plugin shading `ColorRgba` from `Position` coordinates.
#[derive(Default)]
pub struct CrossLangRustMod;

impl GuestPlugin for CrossLangRustMod {
    const NAME: &'static CStr = c"example_03_rust_mod";
    const VERSION: &'static CStr = c"0.2.0";

    fn build(&mut self, app: &mut GuestApp<'_>) -> FfiResult {
        // SAFETY: `PositionVTable` is `#[repr(C)]`, begins with `VTableHeader` at offset 0, and
        // matches the host's static `"bam.v0.example::Position.vtable"` layout for `Position::UUID`.
        let pos_vt = match unsafe {
            app.host().resolve_vtable::<PositionVTable>(
                c"bam.v0.example::Position.vtable",
                <Position as ModComponent>::UUID,
            )
        } {
            Ok(&vt) => vt,
            Err(err) => return err,
        };

        // SAFETY: `ColorRgbaVTable` is `#[repr(C)]`, begins with `VTableHeader` at offset 0, and
        // matches the host's static `"bam.v0.example::ColorRgba.vtable"` layout for `ColorRgba::UUID`.
        let color_vt = match unsafe {
            app.host().resolve_vtable::<ColorRgbaVTable>(
                c"bam.v0.example::ColorRgba.vtable",
                <ColorRgba as ModComponent>::UUID,
            )
        } {
            Ok(&vt) => vt,
            Err(err) => return err,
        };

        let (Some(get_x), Some(get_y), Some(get_z)) = (pos_vt.get_x, pos_vt.get_y, pos_vt.get_z)
        else {
            return FfiResult::NULL_POINTER;
        };
        let (Some(set_r), Some(set_g), Some(set_b), Some(set_a)) = (
            color_vt.set_r,
            color_vt.set_g,
            color_vt.set_b,
            color_vt.set_a,
        ) else {
            return FfiResult::NULL_POINTER;
        };

        app.system(c"rust_color_system")
            .query(|q| q.write::<ColorRgba>().read::<Position>())
            .schedule(ScheduleId::UPDATE)
            .build(move |ctx| {
                while let Some(mut chunk) = ctx.iter().next_chunk_view() {
                    let Some((positions, colors)) =
                        chunk.component_read_write::<Position, ColorRgba>(1, 0)
                    else {
                        return FfiResult::TYPE_MISMATCH;
                    };

                    for (pos, color) in positions.iter().zip(colors.iter_mut()) {
                        let p_ptr = core::ptr::from_ref(pos).cast::<c_void>();
                        let c_ptr = core::ptr::from_mut(color).cast::<c_void>();

                        // SAFETY: `p_ptr` points to a valid `Position` in read column 1, and
                        // `c_ptr` points to a valid disjoint `ColorRgba` in write column 0.
                        let (px, py, pz) = unsafe { (get_x(p_ptr), get_y(p_ptr), get_z(p_ptr)) };

                        let new_r = ((px * 0.05).abs() + 0.1).min(1.0);
                        let new_g = ((py * 0.05).abs() + 0.2).min(1.0);
                        let new_b = ((pz * 0.05).abs() + 0.3).min(1.0);

                        // SAFETY: `c_ptr` is aligned and exclusively borrowed for the current row.
                        unsafe {
                            for res in [
                                set_r(c_ptr, new_r),
                                set_g(c_ptr, new_g),
                                set_b(c_ptr, new_b),
                                set_a(c_ptr, 1.0),
                            ] {
                                if !res.is_ok() {
                                    return res;
                                }
                            }
                        }
                    }
                }
                FfiResult::OK
            })
    }
}

export_mod!(plugin: CrossLangRustMod);
